from pathlib import Path
from html import escape
root=Path(__file__).parent
nav=[('Total Assets','total-assets.html'),('Portfolio','portfolio.html'),('Aditya','aditya.html'),('Retirement Planner','retirement.html')]
def header(active=''):
    links=''.join(f'<a class="nav-link" href="{url}" {"aria-current=\"page\"" if active==name else ""}>{name}</a>' for name,url in nav)
    return f'''<header class="site-header"><div class="container header-inner"><a href="index.html" class="brand"><span class="brand-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="24" height="24" fill="none"><path d="M4 18V13M10 18V9M16 18V5" stroke="currentColor" stroke-width="3" stroke-linecap="round"/><path d="m4 8 5-4 4 1 5-3" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></span>Wealth Dashboard</a><div class="header-right"><a class="avatar" href="upload.html" aria-label="Upload a CAS statement">SG</a></div><nav class="top-nav" aria-label="Main navigation">{links}</nav></div></header>'''
def page(title,active,content,extra=''):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="theme-color" content="#123e9b"/><meta name="description" content="Your investments, goals and retirement in one place"/><title>{title} · Wealth Dashboard</title><link rel="stylesheet" href="css/styles.css"/></head><body>{header(active)}<main class="page"><div class="container">{content}</div></main><div class="footer container">Wealth Dashboard · Private by design · PDFs are processed on your device.</div><script src="js/data.js" defer></script><script src="js/live-data.js" defer></script><script src="js/main.js" defer></script>{extra}</body></html>'''
def metric(label,value,delta=None,icon=None,delta_class='positive',classes=''):
    return f'''<div class="card kpi-card {classes}">{f'<span class="icon-tile">{icon}</span>' if icon else ''}<div><div class="metric-label">{label}</div><div class="metric-value">{value}</div>{f'<div class="delta {delta_class}">{delta}</div>' if delta else ''}</div></div>'''
def fundrow(name,inv,current,gain,category='',swatch='#3277ff'):
    color='positive' if str(gain).startswith('+') else 'negative'
    return f'''<tr><td><div class="fund-cell"><i class="swatch" style="background:{swatch}"></i><strong>{name}</strong></div></td>{f'<td><span class="category-tag">{category}</span></td>' if category else ''}<td class="number">{inv}</td><td class="number">{current}</td><td class="number {color}"><strong>{gain}</strong></td></tr>'''

# Upload CAS
upload = '''<section class="upload-layout"><div class="upload-illustration"><div class="doc-art" aria-hidden="true"><div class="doc-paper"><i></i><i></i><i></i></div><div class="doc-coin">₹</div></div><div class="upload-intro"><span class="chip active">✦ Your investments, in one place</span><h1>Build your<br/> Wealth Dashboard</h1><p>Upload your Consolidated Account Statement and explore your family's mutual funds, portfolio, goals and retirement planning.</p><div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:22px"><span class="chip">🔒 On-device processing</span><span class="chip">📈 Clear portfolio insights</span></div></div></div><form id="uploadForm" class="card upload-shell" novalidate><span class="eyebrow">GET STARTED</span><h2>Upload your CAS</h2><p>One upload powers both Portfolio and Aditya dashboards. Your files stay in your browser.</p><label class="field-label" for="casFiles">CAS PDF files</label><label class="file-field" for="casFiles"><input id="casFiles" type="file" accept=".pdf,application/pdf" multiple/><span class="icon-tile">📄</span><span class="choose">Choose PDF files</span><span class="filename" id="fileName">No file selected</span></label><label class="field-label" for="pdfPassword">PDF password (same for all files)</label><div class="password-wrap"><input id="pdfPassword" type="password" autocomplete="off" placeholder="Enter password"/><button id="togglePassword" type="button" aria-label="Show PDF password">Show</button></div><button type="submit" class="primary-button">Build my dashboard →</button><a href="total-assets.html" class="demo-link">Explore the sample dashboard first →</a><div id="formResult" class="form-result" role="status"></div><div class="privacy"><span>🛡️</span><span>Your statement is parsed on your device. Only processed holdings stay in this browser tab; your PDF and password are never saved.</span></div></form></section>'''
